import{_ as s,l as i,o as e,c as o,v as t,p as l,x as r,d as p,i as d,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"稀疏图","description":"","frontmatter":{"title":"稀疏图","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/sparse-graph.md","filePath":"cs/sparse-graph.md","lastUpdated":1789023840000}'),m={name:"cs/sparse-graph.md"};function c(_,a,E,u,A,S){const n=i("Mermaid");return e(),o("div",null,[a[1]||(a[1]=t('<h1 id="稀疏图" tabindex="-1">稀疏图 <a class="header-anchor" href="#稀疏图" aria-label="Permalink to &quot;稀疏图&quot;">​</a></h1><div class="epigraph"><p>$m$ 随 $n$ 近似线性时，任何 $\\Theta(n^2)$ 的表示或算法都在付不存在的边的账。</p><footer>—— 据 Cormen, Leiserson, Rivest and Stein, Introduction to Algorithms 整理</footer></div><p><a href="/cs/adj-list-matrix">上一课</a>对比了矩阵与表。<a href="/cs/adj-list-matrix">渐近记号</a>已经能写 \\(O(n+m)\\)。<a href="/cs/locality-principle">局部性原理</a>要求顺序扫真实存在的边。本课不重画两种结构。缺口是把<strong>稀疏</strong>写成工作假设：平面图、有界度数、随机图的常见区段里 \\(m=O(n)\\) 或 \\(O(n\\log n)\\)，邻接表（及压缩行存储）成为默认，矩阵只留给稠密或代数。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>若每次分析都按最坏 \\(m=\\Theta(n^2)\\)，表的优点写不出来，BFS 也会被写成 \\(\\Theta(n^2)\\)。缺口不是新的指针类型，而是约定：主干算法用 \\(n\\) 与 \\(m\\) 两个参数，稀疏意味着 \\(m\\ll n^2\\)，实现不得把不存在的边扫一遍。</p><p>CSR：把所有出边拼成一个数组，另用 \\(n+1\\) 个偏移标记每顶点的段。枚举连续，空间仍 \\(\\Theta(n+m)\\)，无指针。这是表的数组化，针对稀疏。</p><p><span class="marginnote">稀疏不是「边很少到没有结构」。社交图、网格、道路网都稀疏却仍有局部团。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>声明输入规模为 \\((n,m)\\)。建图用表或 CSR，拒绝为问边而分配 \\(n^2\\) 除非 \\(m\\) 已接近。需要 \\(O(1)\\) 问边时，对稀疏图用边散列，不用矩阵。</p>',9)),(e(),l(h,null,{default:r(()=>[d(n,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20SP%5B%22m%20%E2%89%AA%20n%C2%B2%22%5D%20--%3E%20CSR%5B%22CSR%2F%E9%82%BB%E6%8E%A5%E8%A1%A8%22%5D%0A%20%20SP%20--%3E%20ALG%5B%22%E7%AE%97%E6%B3%95%E5%86%99%E6%88%90%20%CE%98(n%2Bm)%22%5D%0A%20%20DEN%5B%22m%20%3D%20%CE%98(n%C2%B2)%22%5D%20--%3E%20MAT%5B%22%E7%9F%A9%E9%98%B5%E5%8F%AF%E6%8E%A5%E5%8F%97%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<p>度分布可以偏斜：少数顶点 \\(\\deg=\\Theta(n)\\)，表仍正确，只是这些顶点的枚举本身就 \\(\\Theta(n)\\)。稀疏指全局 \\(m\\)，不是每个度都小。建图时若预先知道 \\(m\\)，一次分配边数组，避免链表节点逐条堆分配。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>后课 BFS/DFS/最短路的界一律带 \\(m\\)。稀疏假设让这些算法接近线性。稠密图用矩阵乘法或直接 \\(\\Theta(n^2)\\) 扫描可能更简单，那是另一分支，主干先走稀疏。</p><p>NUMA 与 cache：CSR 顺序扫边数组，空间局部性好于指针表，这是稀疏图在现代机器上的实现注脚，不改变 \\(\\Theta(n+m)\\)。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入图稀疏化算法（cut sparsisifiers），不把「稀疏」写成矩阵里零的比例以外的随机矩阵理论。动态边更新下 CSR 重建有代价，动态图可用邻接动态数组。</p><p>后课默认：图是稀疏给出的，表示是表或 CSR。无环有向是再加一条约束，用来预备拓扑序。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>稀疏：\\(m\\) 远小于 \\(n^2\\)；复杂度必须显式带 \\(m\\)。</li><li>CSR 把邻接表收成连续数组，枚举吃局部性。</li><li>有向无环作为表示约束，下一课 DAG。</li><li>稀疏指全局 \\(m\\)，不是每个顶点度数都小。</li><li>出处：Cormen et al. 图算法章对 \\(n,m\\) 参数的用法。</li></ul>',9))])}const C=s(m,[["render",c]]);export{f as __pageData,C as default};
